import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On an n×n board filled with zeros, an operation consists of choosing exactly {q} distinct rows and {q} distinct columns, then adding 1 to each of the {q}^2 intersection cells of the chosen rows and columns. If it is possible, via a positive number of such operations, to make all row sums equal and all column sums equal to the same value, define f(n; {q}) as the minimum number of operations; otherwise set f(n; {q}) = 0. Compute S = sum_{n = {lower_n}}^{ {upper_n} } f(n; {q}).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate parameters ensuring non-trivial instances
# We want a decent portion of n in [lower_n, upper_n] to be >= q so f(n; q) > 0 often.
import math
for _ in range(1000):
    q = rng.randint(2, 30)
    # Choose a range length moderately large to avoid trivial sums
    length = rng.randint(800, 8000)
    L_candidate = rng.randint(2, 200000)
    U_candidate = L_candidate + length
    # Ensure at least half of the interval contributes nonzero terms
    nonzero_start = max(L_candidate, q)
    nonzero_count = max(0, U_candidate - nonzero_start + 1)
    total_count = U_candidate - L_candidate + 1
    if total_count <= 0:
        continue
    ratio = nonzero_count / total_count
    if ratio < 0.5:
        continue
    # Compute answer to check size not degenerate
    s = 0
    for n in range(L_candidate, U_candidate + 1):
        if n < q:
            continue
        s += n // math.gcd(n, q)
    # Avoid extremely small or extremely huge answers
    if s < 1000:
        continue
    if s > 10**10:
        # Too large; shrink the interval
        U_candidate = L_candidate + rng.randint(800, 3000)
        # Recompute nonzero count
        nonzero_start = max(L_candidate, q)
        nonzero_count = max(0, U_candidate - nonzero_start + 1)
        total_count = U_candidate - L_candidate + 1
        ratio = nonzero_count / total_count
        if ratio < 0.5:
            continue
    return {"lower_n": L_candidate, "upper_n": U_candidate, "q": q}
# Fallback (unlikely)
return {"lower_n": 1000, "upper_n": 5000, "q": 7}

    def verifier(assign):
# Verify input shape and recompute the correct answer.
# Return (True, answer) when valid; else (False, None).
import math
# Basic structure checks
if not isinstance(assign, dict):
    # invalid assignment
    return (False, None)  # invalid
required = ["lower_n", "upper_n", "q"]
for k in required:
    if k not in assign:
        return (False, None)  # missing slot
lower_n = assign["lower_n"]
upper_n = assign["upper_n"]
q = assign["q"]
# Type checks
if not (isinstance(lower_n, int) and isinstance(upper_n, int) and isinstance(q, int)):
    return (False, None)  # wrong types
# Domain constraints
if q < 2:
    return (False, None)  # operations definition requires at least 2
if lower_n > upper_n:
    return (False, None)  # invalid range
if lower_n < 1:
    return (False, None)  # n must be positive
# Compute f(n; q) using proven formula:
# If n < q, no operation is possible (cannot pick q distinct rows/columns), hence f(n; q) = 0.
# If n >= q, the minimum number of operations equals n / gcd(n, q).
total = 0
for n in range(lower_n, upper_n + 1):
    if n < q:
        continue
    g = math.gcd(n, q)
    total += n // g
return (True, total)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

